import{_ as o,o as t,c as s,a2 as a}from"./chunks/framework.BxRroOcN.js";const m=JSON.parse('{"title":"Storybook is the component workshop of the design system","description":"","frontmatter":{"status":"accepted","date":"2026-11-14T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0028-storybook-is-the-component-workshop-of-the-design-system.md","filePath":"docs/adr/0028-storybook-is-the-component-workshop-of-the-design-system.md"}'),n={name:"docs/adr/0028-storybook-is-the-component-workshop-of-the-design-system.md"};function i(r,e,d,h,c,l){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="storybook-is-the-component-workshop-of-the-design-system" tabindex="-1">Storybook is the component workshop of the design system <a class="header-anchor" href="#storybook-is-the-component-workshop-of-the-design-system" aria-label="Permalink to &quot;Storybook is the component workshop of the design system&quot;">​</a></h1><p>The Vue components of <code>web/ui</code> (<a href="./0023-the-websites-share-one-vue-and-daisyui-design-system">ADR 0023</a>) each have stories in <code>web/storybook</code>: one story per state, with the checks that state must keep. The docs site publishes the built Storybook under <code>/storybook/</code> and embeds stories on its <a href="https://tkint.github.io/coach-poulpy/component-workshop" target="_blank" rel="noreferrer">Component workshop</a> page, so the docs site stays the one place the owner reviews.</p><h2 id="what-it-means" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means" aria-label="Permalink to &quot;What it means&quot;">​</a></h2><ul><li><strong>One story file per component</strong>, in <code>web/storybook/stories/Cp*.stories.ts</code>: a story for each state a person can reach (closed and open for a select, a menu or a sheet; empty, filled, hinted, invalid and disabled for a field). A new or changed component adds or updates its stories in the same PR.</li><li><strong>A <code>play</code> function per behaviour</strong>, run as a test in Chromium by <code>npm test -w storybook</code> (Vitest and the Storybook addon). A popover that opens on page load, an Escape that does not close a panel or a disabled button that still works fails CI.</li><li><strong>Every story is also checked for accessibility</strong> (axe, through <code>@storybook/addon-a11y</code>), in light and dark. A finding fails CI. A story that cannot pass yet is marked <code>a11y: { test: &#39;todo&#39; }</code> with a <code>// CLEANUP:</code> comment that names the fix.</li><li><strong>Docs pages come from the stories.</strong> Every component has an autodocs page that lists all its stories one under the other, with their code.</li><li><strong>The theme is the real one.</strong> The workshop builds Tailwind, DaisyUI, <code>tokens.css</code> and <code>theme.css</code> as the web app does, with the stories as a source, and a toolbar switch sets <code>data-theme</code> to light or dark.</li><li><strong>Agents read it through MCP.</strong> <code>@storybook/addon-mcp</code> serves the running workshop at <code>http://localhost:6006/mcp</code>, declared in <code>.mcp.json</code>, so an agent can find the stories that render a component, preview them and run the story tests while it builds (<a href="./../agents/storybook-mcp">Storybook MCP</a>).</li><li><strong>The hand-built component pages are gone.</strong> The Web components and Tokens pages of the docs site moved into the workshop (ADR 0029), so a component is described once.</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><ul><li>The Web components page was a hand-built gallery: nothing checked the states it showed, and popovers that opened on page load went unnoticed. A story with a <code>play</code> function checks that every time.</li><li>Storybook supports Vue 3 and Vite directly, has the test and accessibility tooling in one place, and is widely maintained.</li><li><a href="https://histoire.dev" target="_blank" rel="noreferrer">Histoire</a> is lighter and Vue-only, but its testing and accessibility tooling is thinner, and it is updated less often.</li><li>Storybook builds to static files, so the docs site publishes it like its other assets.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><code>web/</code> gains the <code>web/storybook</code> workspace. Its dependencies are pinned to exact versions, like DaisyUI and Tailwind.</li><li>The docs build runs <code>storybook build</code>, and the web job in CI runs the stories as tests, which needs Playwright&#39;s Chromium (<code>npx playwright install --with-deps chromium</code>).</li><li>Locally, <code>CHROMIUM_PATH</code> points the tests at a Chromium already on the machine.</li></ul>',8)])])}const y=o(n,[["render",i]]);export{m as __pageData,y as default};
